from docx import Document


def create_approval_note(
    findings,
    recommendation,
    output_path
):

    doc = Document()

    doc.add_heading(
        "CORRECTIVE MAINTENANCE APPROVAL NOTE",
        level=1
    )

    doc.add_paragraph(
        "Generated by Sovereign AI Workbench"
    )

    doc.add_heading(
        "Inspection Findings",
        level=2
    )

    doc.add_paragraph(findings)

    doc.add_heading(
        "Recommended Action",
        level=2
    )

    doc.add_paragraph(recommendation)

    doc.add_heading(
        "Governance Status",
        level=2
    )

    doc.add_paragraph(
        "Prepared by AI — Human approval required."
    )

    doc.save(output_path)